def mathvista_get_test_idx(data,task = None):
    list_task = task.split("_")
    test_idx = []
    for tk in list_task:
        for i,j in data.items():
            if task == "ALL" or j["metadata"]["task"] == mathvista_dict[tk]:
                test_idx.append(i)
    return test_idx

def charxiv_get_test_idx(data,task = None):
    test_idx = []
    for i,j in data.items():
        if task == "ALL" or j["category"] == charxiv_dict[task]:
            test_idx.append(i)
    return test_idx

def mathvision_get_test_idx(data,task = None):
    test_idx = []
    for i,j in data.items():
        if task == "ALL":
            test_idx.append(i)
    return test_idx

def load_jsonl(file_name):
    with open(file_name, "r", encoding="utf-8") as f:
        data = [json.loads(line) for line in f]
    return data


